import { SharedArray } from 'k6/data';
import { sleep } from 'k6';

import { challengesPage } from './queries/challenges.js';
import { profilePage } from './queries/profile.js';
import { standingsGlobalPage } from './queries/standings-global.js';
import { standingsLocalPage } from './queries/standings-local.js';
import { standingsUnitPage } from './queries/standings-unit.js';

// Load configuration from JSON file generated by tokengen
const config = JSON.parse(open('../config.json'));

// SharedArray ensures tokens are only loaded once and shared across VUs
const tokens = new SharedArray('tokens', function () {
    return config.tokens;
});

// Get base URL from config
const baseUrl = config.baseUrl;

// Test configuration with customizable parameters via environment variables
export const options = {
    scenarios: {
        // Scenario 1: Steady-state load (typical usage pattern)
        // Ramps to target VUs in 5 seconds
        steady_load: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '5s', target: parseInt(__ENV.STEADY_VUS) || 50 },
                { duration: __ENV.DURATION || '5m', target: parseInt(__ENV.STEADY_VUS) || 50 },
            ],
            exec: 'steadyLoad',
        },
        // Scenario 2: Spike test (simulates traffic surge)
        // Fast ramp: 5s to peak, hold, 5s down
        spike_test: {
            executor: 'ramping-vus',
            startVUs: 0,
            stages: [
                { duration: '5s', target: parseInt(__ENV.SPIKE_PEAK) || 500 },
                { duration: __ENV.SPIKE_HOLD || '2m', target: parseInt(__ENV.SPIKE_PEAK) || 500 },
                { duration: '5s', target: 0 },
            ],
            exec: 'spikeTest',
            startTime: __ENV.SPIKE_START || '0s',
        },
        // Scenario 3: Leaderboard stress (focused load on leaderboard queries)
        // Pre-allocates VUs for instant ramp
        leaderboard_stress: {
            executor: 'constant-arrival-rate',
            rate: parseInt(__ENV.LEADERBOARD_RPS) || 100,
            timeUnit: '1s',
            duration: __ENV.LEADERBOARD_DURATION || '5m',
            preAllocatedVUs: parseInt(__ENV.LEADERBOARD_RPS) || 100,
            maxVUs: 1000,
            exec: 'leaderboardStress',
            startTime: __ENV.LEADERBOARD_START || '0s',
        },
    },
    thresholds: {
        // HTTP request duration thresholds
        http_req_duration: ['p(95)<500', 'p(99)<1000'],
        // HTTP request failure rate
        http_req_failed: ['rate<0.01'],
        // GraphQL-specific error rate
        graphql_errors: ['rate<0.01'],
    },
};

/**
 * Get a random token from the pool
 * Each VU gets assigned tokens based on its ID for some consistency,
 * but we also add randomness for realistic distribution
 */
function getRandomToken() {
    const index = Math.floor(Math.random() * tokens.length);
    return tokens[index];
}

/**
 * Steady-state load: weighted distribution of all page queries
 * This simulates typical user behavior patterns
 */
export function steadyLoad() {
    const { token } = getRandomToken();

    // Weighted distribution matching expected user behavior:
    // - Challenges page: 30% (main entry point)
    // - Profile page: 20% (checking progress)
    // - Global standings: 20% (competitive users)
    // - Local standings: 15% (checking church ranking)
    // - Unit standings: 15% (checking team ranking)
    const rand = Math.random();

    if (rand < 0.30) {
        challengesPage(baseUrl, token);
    } else if (rand < 0.50) {
        profilePage(baseUrl, token);
    } else if (rand < 0.70) {
        standingsGlobalPage(baseUrl, token);
    } else if (rand < 0.85) {
        standingsLocalPage(baseUrl, token);
    } else {
        standingsUnitPage(baseUrl, token);
    }

    // Small random sleep to simulate realistic user think time
    sleep(Math.random() * 0.5 + 0.1);
}

/**
 * Spike test: same query distribution but under ramping load
 */
export function spikeTest() {
    steadyLoad();
}

/**
 * Leaderboard stress: focused testing of leaderboard queries
 * These are typically the most database-intensive queries
 */
export function leaderboardStress() {
    const { token } = getRandomToken();

    // Distribution focused on leaderboard queries:
    // - Global standings: 50% (most common)
    // - Local standings: 30% (church-filtered)
    // - Unit standings: 20% (team-specific)
    const rand = Math.random();

    if (rand < 0.50) {
        standingsGlobalPage(baseUrl, token);
    } else if (rand < 0.80) {
        standingsLocalPage(baseUrl, token);
    } else {
        standingsUnitPage(baseUrl, token);
    }
}

/**
 * Default function (runs if no specific scenario is selected)
 */
export default function () {
    steadyLoad();
}

/**
 * Setup function - runs once before the test starts
 */
export function setup() {
    console.log(`Load test starting with ${tokens.length} user tokens`);
    console.log(`Target URL: ${baseUrl}`);
    return { tokenCount: tokens.length };
}

/**
 * Teardown function - runs once after the test ends
 */
export function teardown(data) {
    console.log(`Load test completed. Used ${data.tokenCount} user tokens.`);
}
